3	import (
4		"context"
5		"errors"
6		"log/slog"
7		"time"
8	)
9	
10	const (
11		minBackoff = time.Second
12		maxBackoff = 30 * time.Second
13	)
14	
15	// UpdatesGetter — источник апдейтов для long polling.
16	type UpdatesGetter interface {
17		GetUpdates(ctx context.Context, offset int64) ([]Update, error)
18	}
19	
20	// MessageHandler обрабатывает одно текстовое сообщение.
21	type MessageHandler interface {
22		Handle(ctx context.Context, chatID int64, text string)
23	}
24	
25	// Poller крутит цикл getUpdates и раздаёт сообщения обработчику.
26	type Poller struct {
27		updates UpdatesGetter
28		handler MessageHandler
29		log     *slog.Logger
30		wait    func(ctx context.Context, d time.Duration) error // подменяется в тестах
31	}
32	
33	// NewPoller создаёт poller.
34	func NewPoller(updates UpdatesGetter, handler MessageHandler, log *slog.Logger) *Poller {
35		return &Poller{updates: updates, handler: handler, log: log, wait: sleep}
36	}
37	
38	// Run работает до отмены ctx (возвращает ctx.Err()) или до отказа Telegram в токене.
39	func (p *Poller) Run(ctx context.Context) error {
40		var offset int64
41		backoff := minBackoff
42		for {
43			if err := ctx.Err(); err != nil {
44				return err
45			}
46			updates, err := p.updates.GetUpdates(ctx, offset)
47			if err != nil {
48				if ctx.Err() != nil {
49					return ctx.Err()
50				}
51				if errors.Is(err, ErrUnauthorized) {
52					return err
53				}
54				delay := backoff
55				var ra *retryAfterError
56				if errors.As(err, &ra) && ra.after > 0 {
57					delay = ra.after
58				} else {
59					backoff = min(backoff*2, maxBackoff)
60				}
61				p.log.Warn("get updates", "err", err, "retry_in", delay.String())
62				if err := p.wait(ctx, delay); err != nil {
63					return err
64				}
65				continue
66			}
67			backoff = minBackoff
68			for _, u := range updates {
69				offset = max(offset, u.UpdateID+1)
70				if u.Message == nil || u.Message.Text == "" {
71					continue
72				}
73				p.handler.Handle(ctx, u.Message.Chat.ID, u.Message.Text)
74			}
75		}
76	}
77	
78	// sleep ждёт d или отмены ctx.
79	func sleep(ctx context.Context, d time.Duration) error {
80		t := time.NewTimer(d)
81		defer t.Stop()
82		select {
83		case <-ctx.Done():
84			return ctx.Err()
85		case <-t.C:
86			return nil
87		}
88	}
