21		if w.Description != "" {
22			b.WriteString("\n☁️ " + capitalize(w.Description))
23		}
24		b.WriteString("\n💧 Влажность " + strconv.Itoa(w.Humidity) + " %")
25		b.WriteString("\n💨 Ветер " + strconv.Itoa(int(math.Round(w.WindSpeed))) + " м/с, " + windDirection(w.WindDeg))
26		return b.String()
27	}
28	
29	// formatTemp: 12.4 → "+12", -2.6 → "-3", -0.4 → "0".
30	func formatTemp(t float64) string {
31		n := int(math.Round(t))
32		if n > 0 {
33			return "+" + strconv.Itoa(n)
34		}
35		return strconv.Itoa(n)
36	}
37	
38	// windDirection переводит градусы в один из 8 румбов; 0 = север.
39	func windDirection(deg int) string {
40		dirs := [...]string{"С", "СВ", "В", "ЮВ", "Ю", "ЮЗ", "З", "СЗ"} // по часовой, от севера
41		deg = (deg%360 + 360) % 360
42		return dirs[int(math.Round(float64(deg)/45))%len(dirs)]
43	}
44	
45	// capitalize делает первую руну заглавной.
46	func capitalize(s string) string {
47		r, size := utf8.DecodeRuneInString(s)
48		if r == utf8.RuneError {
49			return s
50		}
51		return string(unicode.ToUpper(r)) + s[size:]
52	}
